+++ b/mailnews/search/src/nsMsgBodyHandler.cpp
@@ -563,6 +563,9 @@ void nsMsgBodyHandler::SniffPossibleMIMEHeader(const nsCString& line) {
     if (!m_boundaries.Contains(boundary)) m_boundaries.AppendElement(boundary);
   }

+  // For simple text/plain or text/html messages we don't need the charset,
+  // since the caller of `MatchBody()` already provides the overall message
+  // charset.
   if (m_isMultipart && (start = lowerCaseLine.Find("charset=")) != kNotFound) {
     start += 8;  // strlen("charset=")
     bool foundQuote = false;
diff --git a/mailnews/search/src/nsMsgSearchTerm.cpp b/mailnews/search/src/nsMsgSearchTerm.cpp
index f669ad448df..053fdbefbca 100644
--- a/mailnews/search/src/nsMsgSearchTerm.cpp
+++ b/mailnews/search/src/nsMsgSearchTerm.cpp
@@ -783,7 +783,7 @@ NS_IMETHODIMP nsMsgSearchTerm::MatchUint32HdrProperty(nsIMsgDBHdr* aHdr,
 }

 nsresult nsMsgSearchTerm::MatchBody(nsIMsgSearchScopeTerm* scope,
-                                    const char* folderCharset, nsIMsgDBHdr* msg,
+                                    const char* msgCharset, nsIMsgDBHdr* msg,
                                     bool* pResult) {
   NS_ENSURE_ARG_POINTER(pResult);
   nsresult rv = NS_OK;
@@ -836,9 +836,8 @@ nsresult nsMsgSearchTerm::MatchBody(nsIMsgSearchScopeTerm* scope,
     if (!compare.IsEmpty()) {
       char startChar = (char)compare.CharAt(0);
       if (startChar != '\r' && startChar != '\n') {
-        rv = MatchString(compare,
-                         charset.IsEmpty() ? folderCharset : charset.get(),
-                         &result);
+        rv = MatchString(
+            compare, charset.IsEmpty() ? msgCharset : charset.get(), &result);
       }
       compare.Truncate();
     }
